// Load Credentials v5 — v4 architecture + v3 full personalization
const prev = $('Extract Payload').first().json;
const p = prev.persona || {};
const t = p.tokens || {};
const lang = p.language_preference || 'th';

const i18nMap = {
  th: { not_connected:'ยังไม่ได้เชื่อมต่อ', configure:'กรุณาตั้งค่าที่ /dashboard/api-settings', success:'สำเร็จ', error:'เกิดข้อผิดพลาด', completed:'เสร็จแล้ว' },
  en: { not_connected:'Not connected', configure:'Please configure at /dashboard/api-settings', success:'Success', error:'Error occurred', completed:'Completed' },
  ja: { not_connected:'接続されていません', configure:'/dashboard/api-settingsで設定してください', success:'成功しました', error:'エラーが発生しました', completed:'完了しました' },
  zh: { not_connected:'未连接', configure:'请在 /dashboard/api-settings 配置', success:'成功', error:'发生错误', completed:'已完成' }
};
const i18n = i18nMap[lang] || i18nMap['en'];

const get = (envKey, payloadKey) => t[payloadKey] || p[payloadKey] || process.env[envKey] || '';

const creds = {
  google_access_token:    get('GOOGLE_ACCESS_TOKEN','google_access_token'),
  google_refresh_token:   get('GOOGLE_REFRESH_TOKEN','google_refresh_token'),
  microsoft_access_token: get('MICROSOFT_ACCESS_TOKEN','microsoft_access_token'),
  outlook_access_token:   get('MICROSOFT_ACCESS_TOKEN','microsoft_access_token'),
  telegram_bot_token:     get('TELEGRAM_BOT_TOKEN','telegram_bot_token'),
  discord_bot_token:      get('DISCORD_BOT_TOKEN','discord_bot_token'),
  slack_bot_token:        get('SLACK_BOT_TOKEN','slack_bot_token'),
  twitter_bearer_token:   get('TWITTER_BEARER_TOKEN','twitter_bearer_token'),
  facebook_access_token:  get('FACEBOOK_ACCESS_TOKEN','facebook_access_token'),
  linkedin_access_token:  get('LINKEDIN_ACCESS_TOKEN','linkedin_access_token'),
  spotify_access_token:   get('SPOTIFY_ACCESS_TOKEN','spotify_access_token'),
  youtube_api_key:        get('YOUTUBE_API_KEY','youtube_api_key'),
  line_notify_token:      get('LINE_NOTIFY_TOKEN','line_notify_token'),
  google_maps_key:        get('GOOGLE_MAPS_API_KEY','google_maps_key'),
  brave_api_key:          get('BRAVE_API_KEY','brave_api_key'),
  openweathermap_key:     get('OPENWEATHERMAP_API_KEY','openweathermap_key'),
  fal_api_key:            get('FAL_API_KEY','fal_api_key'),
  elevenlabs_api_key:     get('ELEVENLABS_API_KEY','elevenlabs_api_key'),
  elevenlabs_voice_id:    get('ELEVENLABS_VOICE_ID','elevenlabs_voice_id'),
  unsplash_access_key:    get('UNSPLASH_ACCESS_KEY','unsplash_access_key'),
  nutritionix_app_id:     get('NUTRITIONIX_APP_ID','nutritionix_app_id'),
  nutritionix_api_key:    get('NUTRITIONIX_API_KEY','nutritionix_api_key'),
  finnhub_api_key:        get('FINNHUB_API_KEY','finnhub_api_key'),
  ha_url:                 get('HOME_ASSISTANT_URL','ha_url'),
  ha_token:               get('HOME_ASSISTANT_TOKEN','ha_token'),
  sonos_api_url:          get('SONOS_HTTP_API_URL','sonos_api_url'),
  lastfm_api_key:         get('LASTFM_API_KEY','lastfm_api_key'),
  lastfm_username:        get('LASTFM_USERNAME','lastfm_username'),
  lastfm_session_key:     get('LASTFM_SESSION_KEY','lastfm_session_key'),
  internal_auth_token:    get('INTERNAL_AUTH_TOKEN','internal_auth_token'),
  n8n_base_url:           get('N8N_BASE_URL','n8n_base_url'),
  database_url:           prev.databaseUrl || get('DATABASE_URL','database_url'),
  github_token:           get('GITHUB_TOKEN','github_token'),
};

// OpenRouter keys for LLM fallback (same as v4)
const userOrKey  = t.openrouter_access_token || '';
const sysOrKey   = process.env.OPENROUTER_API_KEY || '';
const PAID_MODEL = 'anthropic/claude-haiku-4-5';
const FREE_MODEL = 'meta-llama/llama-3.3-70b-instruct:free';

// ── Build USER_CONTEXT (v3 depth, restored in v5) ─────────────
const userContextParts = [];

if (p.name) userContextParts.push(`Name: ${p.name}`);
if (p.interests?.length > 0) userContextParts.push(`Interests: ${p.interests.join(', ')}`);
if (p.personality_notes) userContextParts.push(`Personality: ${p.personality_notes}`);
if (p.key_facts?.length > 0) {
  userContextParts.push(`Key Facts:\n${p.key_facts.map(f => `  - ${f}`).join('\n')}`);
}
if (p.physical_stats && Object.keys(p.physical_stats).length > 0) {
  const stats = Object.entries(p.physical_stats).map(([k,v]) => `${k}: ${v}`).join(', ');
  userContextParts.push(`Physical Stats: ${stats}`);
}
if (p.ethical_profile) {
  const ep = p.ethical_profile;
  userContextParts.push(
    `Growth Stage: ${ep.growth_stage} (${ep.growth_stage_label})` +
    (ep.top_strengths?.length > 0 ? ` | Strengths: ${ep.top_strengths.join(', ')}` : '')
  );
}
if (p.relevant_memories?.length > 0) {
  const memStr = p.relevant_memories.map(m => `  [${m.type}]: ${m.summary}`).join('\n');
  userContextParts.push(`Recent Memories (static snapshot):\n${memStr}`);
}

const USER_CONTEXT = userContextParts.length > 0
  ? `\n\n## WHAT I KNOW ABOUT YOU:\n${userContextParts.join('\n')}\n`
  : '';

// ── Growth Stage Behavior Guide (restored from v3) ────────────
const stage = p.ethical_profile?.growth_stage || 2;
const GROWTH_GUIDANCE = {
  1: 'User is a beginner — use simple language, be very supportive, patient',
  2: 'User is developing — encourage, guide step by step',
  3: 'User is growing — challenge with open questions, stimulate thinking',
  4: 'User is advanced — engage deeply, give space to explore',
  5: 'User is mature — be a thinking partner, minimal guidance needed'
}[stage] || '';

const connected = Object.entries(creds).filter(([k,v]) => v).map(([k]) => k);

console.log('[Load Credentials v5]', {
  userId: prev.userId?.substring(0,8)+'...',
  connected: connected.length,
  lang,
  hasUserKey: !!userOrKey,
  hasUserContext: USER_CONTEXT.length > 0,
  growthStage: stage
});

return {
  json: {
    ...prev,
    credentials: creds,
    lang, i18n,
    USER_CONTEXT,
    GROWTH_GUIDANCE,
    stage,
    userOrKey, sysOrKey,
    PAID_MODEL, FREE_MODEL,
    _connected: connected,
    _persona: p
  }
};

const input = JSON.parse($input.first().json.query || '{}');
const query = input.query || input.q || '';
const limit = input.limit || 3;
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const userId = ctx.userId;
const dbUrl  = creds.database_url || process.env.DATABASE_URL || '';
const persona = ctx._persona || ctx.persona || {};
const tokens  = persona.tokens || {};
const embedKey = tokens.openrouter_access_token || process.env.OPENROUTER_API_KEY || '';

if (!dbUrl)   return { json: { error: `Database ${i18n.not_connected||'not connected'}`, memories: [] } };
if (!query || query.length < 3) return { json: { error: 'Query too short', memories: [] } };
if (!embedKey) return { json: { error: 'OpenRouter key not configured', memories: [] } };

try {
  const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${embedKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'openai/text-embedding-3-small', input: query })
  });
  if (!embedRes.ok) return { json: { error: `Embed failed: ${embedRes.status}`, memories: [] } };
  const embedData = await embedRes.json();
  const embedding = embedData.data?.[0]?.embedding;
  if (!embedding) return { json: { error: 'No embedding returned', memories: [] } };

  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const vectorStr = `[${embedding.join(',')}]`;
  const result = await pool.query(
    `SELECT content, metadata, created_at,
            1 - (embedding <=> $1::vector) AS similarity
     FROM user_data_schema.memory_embeddings
     WHERE user_id = $2 AND embedding IS NOT NULL
       AND 1 - (embedding <=> $1::vector) > 0.6
     ORDER BY embedding <=> $1::vector LIMIT $3`,
    [vectorStr, userId, limit]
  );
  await pool.end();
  const memories = result.rows.map(r => ({
    content: r.content,
    similarity: parseFloat(r.similarity.toFixed(3)),
    metadata: r.metadata || {},
    date: new Date(r.created_at).toLocaleDateString('th-TH')
  }));
  if (memories.length === 0) return { json: { message: 'No relevant memories found', memories: [], query } };
  return { json: { memories, count: memories.length, query } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}`, memories: [] } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n  || {};
const action = (input.action || 'list_events').toLowerCase();
const token = creds.google_access_token || '';
if (!token) return { json: { error: `Google Calendar ${i18n.not_connected}`, help: i18n.configure, action } };
const baseUrl = 'https://www.googleapis.com/calendar/v3';
let url, method, body;
if (action === 'create_event') {
  url = `${baseUrl}/calendars/primary/events`; method = 'POST';
  body = JSON.stringify({ summary: input.title||'', description: input.description||'', location: input.location||'',
    start: { dateTime: input.start, timeZone: 'Asia/Bangkok' },
    end:   { dateTime: input.end,   timeZone: 'Asia/Bangkok' } });
} else {
  const tMin = input.time_min || new Date().toISOString();
  const tMax = input.time_max || new Date(Date.now()+7*86400000).toISOString();
  url = `${baseUrl}/calendars/primary/events?timeMin=${encodeURIComponent(tMin)}&timeMax=${encodeURIComponent(tMax)}&singleEvents=true&orderBy=startTime&maxResults=20`;
  method = 'GET'; body = null;
}
const res = await fetch(url, { method, headers: { 'Authorization':`Bearer ${token}`, 'Content-Type':'application/json' }, body: body||undefined });
const data = await res.json();
if (!res.ok) return { json: { error: data.error?.message||`Calendar ${i18n.error}`, status: res.status } };
if (action === 'create_event') return { json: { success:true, message:i18n.success, event_id:data.id, title:data.summary, start:data.start, link:data.htmlLink } };
const events = (data.items||[]).map(e => ({ id:e.id, title:e.summary, start:e.start?.dateTime||e.start?.date, end:e.end?.dateTime||e.end?.date, location:e.location||'' }));
return { json: { events, count: events.length } };

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n  || {};
const action = (input.action || 'list_tasks').toLowerCase();
const token = creds.google_access_token || '';
if (!token) return { json: { error: `Google Tasks ${i18n.not_connected}`, help: i18n.configure } };
const base = 'https://tasks.googleapis.com/tasks/v1';
let url, method, body;
if (action === 'create_task') {
  url = `${base}/lists/@default/tasks`; method = 'POST';
  body = JSON.stringify({ title: input.title||'', notes: input.notes||'', due: input.due||null });
} else if (action === 'complete_task') {
  url = `${base}/lists/@default/tasks/${input.task_id}`; method = 'PATCH';
  body = JSON.stringify({ status: 'completed' });
} else {
  url = `${base}/lists/@default/tasks?showCompleted=false&maxResults=20`; method = 'GET'; body = null;
}
const res = await fetch(url, { method, headers: { 'Authorization':`Bearer ${token}`, 'Content-Type':'application/json' }, body: body||undefined });
const data = await res.json();
if (!res.ok) return { json: { error: data.error?.message||`Tasks ${i18n.error}` } };
if (action === 'list_tasks') {
  const tasks = (data.items||[]).map(t => ({ id:t.id, title:t.title, due:t.due, status:t.status }));
  return { json: { tasks, count: tasks.length } };
}
return { json: { success:true, message:i18n.success, task: { id:data.id, title:data.title, status:data.status } } };

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n  || {};
const action   = (input.action   || 'read_inbox').toLowerCase();
const provider = (input.provider || 'gmail').toLowerCase();
if (provider === 'gmail') {
  const token = creds.google_access_token || '';
  if (!token) return { json: { error: `Gmail ${i18n.not_connected}`, help: i18n.configure } };
  if (action === 'send_email') {
    const raw = btoa(`To: ${input.to}\nSubject: ${input.subject}\nContent-Type: text/plain; charset=utf-8\n\n${input.body}`)
      .replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
    const res = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
      method:'POST', headers:{'Authorization':`Bearer ${token}`,'Content-Type':'application/json'},
      body: JSON.stringify({raw}) });
    const data = await res.json();
    if (!res.ok) return { json: { error: data.error?.message||i18n.error } };
    return { json: { success:true, message:i18n.success, message_id:data.id } };
  }
  const q = encodeURIComponent(input.query||'is:unread');
  const listRes = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages?q=${q}&maxResults=${input.max_results||10}`,
    { headers:{'Authorization':`Bearer ${token}`} });
  const listData = await listRes.json();
  const msgs = (listData.messages||[]).slice(0,5);
  const details = await Promise.all(msgs.map(async m => {
    const r = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/${m.id}?format=metadata&metadataHeaders=Subject&metadataHeaders=From`,
      { headers:{'Authorization':`Bearer ${token}`} });
    const d = await r.json();
    const hdrs = {}; (d.payload?.headers||[]).forEach(h => { hdrs[h.name]=h.value; });
    return { id:m.id, from:hdrs['From'], subject:hdrs['Subject'], snippet:d.snippet };
  }));
  return { json: { emails:details, count:details.length, provider:'gmail' } };
}
if (provider === 'outlook') {
  const token = creds.outlook_access_token || '';
  if (!token) return { json: { error: `Outlook ${i18n.not_connected}`, help: i18n.configure } };
  if (action === 'send_email') {
    const res = await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
      method:'POST', headers:{'Authorization':`Bearer ${token}`,'Content-Type':'application/json'},
      body: JSON.stringify({ message:{ subject:input.subject, body:{contentType:'Text',content:input.body}, toRecipients:[{emailAddress:{address:input.to}}] } }) });
    if (res.status===202) return { json:{ success:true, message:i18n.success, provider:'outlook' } };
    const data = await res.json(); return { json:{ error:data.error?.message||i18n.error } };
  }
  const filter = action==='search_email' ? `$search="${input.query||''}"` : '$filter=isRead eq false';
  const res = await fetch(`https://graph.microsoft.com/v1.0/me/messages?${filter}&$top=${input.max_results||10}&$select=id,subject,from,receivedDateTime,bodyPreview`,
    { headers:{'Authorization':`Bearer ${token}`} });
  const data = await res.json();
  const emails = (data.value||[]).map(m => ({ id:m.id, from:m.from?.emailAddress?.address, subject:m.subject, snippet:m.bodyPreview, received:m.receivedDateTime }));
  return { json: { emails, count:emails.length, provider:'outlook' } };
}
return { json: { error:`Use provider: gmail or outlook` } };

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n  || {};
const action   = (input.action   || 'send_message').toLowerCase();
const platform = (input.platform || '').toLowerCase();
if (platform === 'telegram') {
  const bt = creds.telegram_bot_token || '';
  if (!bt) return { json:{ error:`Telegram ${i18n.not_connected}`, help:i18n.configure } };
  if (action==='send_message') {
    const res = await fetch(`https://api.telegram.org/bot${bt}/sendMessage`,
      { method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ chat_id:input.target, text:input.message, parse_mode:'Markdown' }) });
    const data = await res.json();
    if (!data.ok) return { json:{ error:data.description } };
    return { json:{ success:true, message_id:data.result?.message_id, platform:'telegram' } };
  }
  const res = await fetch(`https://api.telegram.org/bot${bt}/getUpdates?limit=20&offset=-20`);
  const data = await res.json();
  const msgs = (data.result||[]).map(u => ({ from:u.message?.from?.username||u.message?.from?.first_name, chat_id:u.message?.chat?.id, text:u.message?.text, date:new Date(u.message?.date*1000).toISOString() })).filter(m=>m.text);
  return { json:{ messages:msgs, count:msgs.length, platform:'telegram' } };
}
if (platform === 'discord') {
  const bt = creds.discord_bot_token || '';
  if (!bt) return { json:{ error:`Discord ${i18n.not_connected}`, help:i18n.configure } };
  if (action==='send_message') {
    const res = await fetch(`https://discord.com/api/v10/channels/${input.target}/messages`,
      { method:'POST', headers:{'Authorization':`Bot ${bt}`,'Content-Type':'application/json'}, body:JSON.stringify({content:input.message}) });
    const data = await res.json();
    if (data.code) return { json:{ error:data.message } };
    return { json:{ success:true, message_id:data.id, platform:'discord' } };
  }
  const res = await fetch(`https://discord.com/api/v10/channels/${input.target}/messages?limit=20`, { headers:{'Authorization':`Bot ${bt}`} });
  const msgs = await res.json();
  return { json:{ messages:(msgs||[]).map(m=>({id:m.id,author:m.author?.username,content:m.content,timestamp:m.timestamp})), platform:'discord' } };
}
if (platform === 'slack') {
  const bt = creds.slack_bot_token || '';
  if (!bt) return { json:{ error:`Slack ${i18n.not_connected}`, help:i18n.configure } };
  if (action==='send_message') {
    const res = await fetch('https://slack.com/api/chat.postMessage',
      { method:'POST', headers:{'Authorization':`Bearer ${bt}`,'Content-Type':'application/json'}, body:JSON.stringify({channel:input.target,text:input.message}) });
    const data = await res.json();
    if (!data.ok) return { json:{ error:data.error } };
    return { json:{ success:true, ts:data.ts, platform:'slack' } };
  }
  const res = await fetch(`https://slack.com/api/conversations.history?channel=${input.target}&limit=20`, { headers:{'Authorization':`Bearer ${bt}`} });
  const data = await res.json();
  if (!data.ok) return { json:{ error:data.error } };
  return { json:{ messages:(data.messages||[]).map(m=>({ts:m.ts,user:m.user,text:m.text})), platform:'slack' } };
}
return { json:{ error:`Unknown platform: ${platform}. Use: telegram, discord, slack` } };

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n  || {};
const platform = (input.platform || '').toLowerCase();
const action   = (input.action   || 'post').toLowerCase();
if (platform === 'twitter' || platform === 'x') {
  const token = creds.twitter_bearer_token || '';
  if (!token) return { json:{ error:`Twitter ${i18n.not_connected}`, help:i18n.configure } };
  if (action==='post_tweet') {
    const res = await fetch('https://api.twitter.com/2/tweets', { method:'POST', headers:{'Authorization':`Bearer ${token}`,'Content-Type':'application/json'}, body:JSON.stringify({text:input.text||''}) });
    const data = await res.json();
    if (!res.ok) return { json:{ error:data.detail||i18n.error } };
    return { json:{ success:true, tweet_id:data.data?.id, platform:'twitter' } };
  }
  if (action==='search_tweets') {
    const res = await fetch(`https://api.twitter.com/2/tweets/search/recent?query=${encodeURIComponent(input.query||'')}&max_results=${input.max_results||10}`, { headers:{'Authorization':`Bearer ${token}`} });
    const data = await res.json();
    return { json:{ tweets:data.data||[], platform:'twitter' } };
  }
  if (action==='get_timeline') {
    const res = await fetch(`https://api.twitter.com/2/users/me/timelines/reverse_chronological?max_results=${input.max_results||10}`, { headers:{'Authorization':`Bearer ${token}`} });
    const data = await res.json();
    return { json:{ tweets:data.data||[], count:(data.data||[]).length, platform:'twitter' } };
  }
  return { json:{ error:`Unknown twitter action: ${action}` } };
}
if (platform === 'youtube') {
  const apiKey = creds.youtube_api_key || '';
  if (!apiKey) return { json:{ error:`YouTube ${i18n.not_connected}`, help:i18n.configure } };
  if (action === 'search') {
    const q = encodeURIComponent(input.query||'');
    const res = await fetch(`https://www.googleapis.com/youtube/v3/search?part=snippet&q=${q}&type=video&maxResults=${input.max_results||5}&key=${apiKey}`);
    const data = await res.json();
    if (!res.ok) return { json:{ error:data.error?.message||i18n.error } };
    return { json:{ videos:(data.items||[]).map(v=>({ id:v.id?.videoId, title:v.snippet?.title, channel:v.snippet?.channelTitle, description:v.snippet?.description?.slice(0,150), url:`https://youtube.com/watch?v=${v.id?.videoId}` })), count:(data.items||[]).length, platform:'youtube' } };
  }
  // get_trending
  const res = await fetch(`https://www.googleapis.com/youtube/v3/videos?part=snippet,statistics&chart=mostPopular&regionCode=${input.region||'TH'}&maxResults=${input.max_results||5}&key=${apiKey}`);
  const data = await res.json();
  if (!res.ok) return { json:{ error:data.error?.message||i18n.error } };
  return { json:{ videos:(data.items||[]).map(v=>({ id:v.id, title:v.snippet?.title, channel:v.snippet?.channelTitle, views:parseInt(v.statistics?.viewCount||0).toLocaleString(), url:`https://youtube.com/watch?v=${v.id}` })), count:(data.items||[]).length, platform:'youtube' } };
}
if (platform === 'facebook') {
  const token = creds.facebook_access_token || '';
  if (!token) return { json:{ error:`Facebook ${i18n.not_connected}`, help:i18n.configure } };
  if (action === 'post') {
    const pageId = input.page_id || 'me';
    const res = await fetch(`https://graph.facebook.com/v18.0/${pageId}/feed`, {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ message:input.message||'', access_token:token }) });
    const data = await res.json();
    if (!res.ok||data.error) return { json:{ error:data.error?.message||i18n.error } };
    return { json:{ success:true, post_id:data.id, platform:'facebook' } };
  }
  const res = await fetch(`https://graph.facebook.com/v18.0/me/feed?fields=id,message,created_time&limit=${input.limit||10}&access_token=${token}`);
  const data = await res.json();
  if (data.error) return { json:{ error:data.error.message } };
  return { json:{ posts:data.data||[], platform:'facebook' } };
}
if (platform === 'linkedin') {
  const token = creds.linkedin_access_token || '';
  if (!token) return { json:{ error:`LinkedIn ${i18n.not_connected}`, help:i18n.configure } };
  if (action === 'post') {
    const profileRes = await fetch('https://api.linkedin.com/v2/userinfo', { headers:{'Authorization':`Bearer ${token}`} });
    const profile = await profileRes.json();
    const authorUrn = `urn:li:person:${profile.sub}`;
    const res = await fetch('https://api.linkedin.com/v2/ugcPosts', {
      method:'POST', headers:{'Authorization':`Bearer ${token}`,'Content-Type':'application/json'},
      body: JSON.stringify({ author:authorUrn, lifecycleState:'PUBLISHED', specificContent:{ 'com.linkedin.ugc.ShareContent':{ shareCommentary:{text:input.text||''}, shareMediaCategory:'NONE' } }, visibility:{ 'com.linkedin.ugc.MemberNetworkVisibility':'PUBLIC' } }) });
    const data = await res.json();
    if (!res.ok) return { json:{ error:data.message||i18n.error } };
    return { json:{ success:true, post_id:data.id, platform:'linkedin' } };
  }
  const res = await fetch('https://api.linkedin.com/v2/shares?q=owners&owners=me&count=10', { headers:{'Authorization':`Bearer ${token}`} });
  const data = await res.json();
  if (!res.ok) return { json:{ error:data.message||i18n.error } };
  return { json:{ shares:data.elements||[], platform:'linkedin' } };
}
return { json:{ error:`Unknown platform: ${platform}. Use: twitter, youtube, facebook, linkedin` } };

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n  || {};
const token = creds.line_notify_token || '';
if (!token) return { json:{ error:`LINE Notify ${i18n.not_connected}`, help:i18n.configure } };
const message = input.message || '';
if (!message) return { json:{ error:i18n.error||'Message required' } };
try {
  const res = await fetch('https://notify-api.line.me/api/notify', {
    method:'POST',
    headers:{'Authorization':`Bearer ${token}`,'Content-Type':'application/x-www-form-urlencoded'},
    body: new URLSearchParams({message})
  });
  const data = await res.json();
  if (!res.ok||data.status!==200) return { json:{ error:i18n.error, details:data.message } };
  return { json:{ success:true, message:i18n.success, status:data.status } };
} catch(e) { return { json:{ error:i18n.error, details:e.message } }; }

// Format Output v5 — normalized for WF2 synthesis
// Dispatch Gate reads: data?.message || data?.response || data?.output || data?.agentOutput || data?.text
// n8n LangChain agent returns output in: output field (primary), then text
const raw  = $input.first().json;
const out  = raw.output || raw.agentOutput || raw.text || raw.message || 'ดำเนินการเสร็จแล้วครับ';
const prev = $('Extract Payload').item.json;
const result = {
  ...prev,
  message:       out,
  response:      out,
  output:        out,
  agentOutput:   out,
  agentCategory: 'secretary',
  processedAt:   new Date().toISOString(),
  _llm_tier:     raw._llm_tier || 'langchain'
};
return { json: result };
